// Fontes gratuitas do radar ViceScope.
// Para adicionar outra fonte depois, inclua mais um objeto nesta lista.
return [
  {
    json: {
      sourceName: 'Rockstar Games - YouTube oficial',
      sourceType: 'official',
      url: 'https://www.youtube.com/feeds/videos.xml?channel_id=UC6VcWc1rAoWdBCM0JxrRQ3A'
    }
  },
  {
    json: {
      sourceName: 'Rockstar Newswire via Google News',
      sourceType: 'official',
      url: 'https://news.google.com/rss/search?q=site%3Arockstargames.com%2Fnewswire+%22Grand+Theft+Auto+VI%22&hl=en-US&gl=US&ceid=US%3Aen'
    }
  },
  {
    json: {
      sourceName: 'Tendencias GTA VI - ultimos 2 dias',
      sourceType: 'news',
      url: 'https://news.google.com/rss/search?q=%28%22GTA+VI%22+OR+%22GTA+6%22+OR+%22Grand+Theft+Auto+VI%22%29+when%3A2d&hl=en-US&gl=US&ceid=US%3Aen'
    }
  }
];

// Mantem somente noticias sobre GTA VI, pontua relevancia
// e impede que a mesma URL seja processada em execucoes futuras.
const memory = $getWorkflowStaticData('global');
const now = Date.now();
const historyTtl = 14 * 24 * 60 * 60 * 1000;
const articleTtl = 7 * 24 * 60 * 60 * 1000;

memory.seen = memory.seen || {};

for (const [key, timestamp] of Object.entries(memory.seen)) {
  if (!timestamp || now - timestamp > historyTtl) delete memory.seen[key];
}

const clean = (value = '') =>
  String(value)
    .replace(/<[^>]*>/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&#39;/g, "'")
    .replace(/&quot;/g, '"')
    .replace(/\s+/g, ' ')
    .trim();

const normalizeUrl = (value = '') => {
  try {
    const url = new URL(value);
    for (const key of [...url.searchParams.keys()]) {
      if (key.startsWith('utm_') || ['gclid', 'fbclid', 'si'].includes(key)) {
        url.searchParams.delete(key);
      }
    }
    url.hash = '';
    return url.toString();
  } catch {
    return String(value).trim();
  }
};

const gtaTerms = [
  'gta vi',
  'gta 6',
  'grand theft auto vi',
  'grand theft auto 6'
];

const strongTerms = [
  'trailer',
  'gameplay',
  'release date',
  'launch',
  'rockstar confirms',
  'rockstar reveals',
  'official',
  'pre-order',
  'map',
  'character',
  'vice city',
  'announcement'
];

const rumorTerms = [
  'rumor',
  'leak',
  'allegedly',
  'reportedly',
  'insider claims',
  'might',
  'could be'
];

const results = [];

for (const item of $input.all()) {
  const data = item.json || {};
  const title = clean(data.title);
  const description = clean(
    data.contentSnippet || data.content || data.summary || data.description
  );
  const url = normalizeUrl(data.link || data.guid || data.url);
  const author = clean(data.creator || data.author || data['dc:creator']);
  const text = `${title} ${description}`.toLowerCase();

  if (!title || !url) continue;
  if (!gtaTerms.some(term => text.includes(term))) continue;

  const publishedRaw = data.isoDate || data.pubDate || data.published || data.date;
  const publishedMs = publishedRaw ? new Date(publishedRaw).getTime() : now;
  if (Number.isFinite(publishedMs) && now - publishedMs > articleTtl) continue;

  const key = url.toLowerCase().replace(/\/$/, '');
  if (memory.seen[key]) continue;

  const officialRockstar =
    url.includes('rockstargames.com') ||
    author.toLowerCase().includes('rockstar games') ||
    (url.includes('youtube.com') && text.includes('rockstar'));

  let score = officialRockstar ? 95 : 55;
  score += strongTerms.filter(term => text.includes(term)).length * 4;
  score -= rumorTerms.filter(term => text.includes(term)).length * 7;
  score = Math.max(0, Math.min(100, score));

  memory.seen[key] = now;

  results.push({
    json: {
      radarEmpty: false,
      title,
      url,
      author: author || (officialRockstar ? 'Rockstar Games' : 'Fonte externa'),
      publishedAt: Number.isFinite(publishedMs)
        ? new Date(publishedMs).toISOString()
        : new Date().toISOString(),
      summary: description.slice(0, 700),
      official: officialRockstar,
      reliability: officialRockstar ? 'official' : 'needs_verification',
      viralScore: score
    }
  });
}

results.sort((a, b) => b.json.viralScore - a.json.viralScore);

if (results.length === 0) {
  return [{
    json: {
      radarEmpty: true,
      status: 'Nenhuma noticia nova sobre GTA VI nesta execucao.'
    }
  }];
}

return results.slice(0, 25);

const input = $input.all();

if (input.length === 1 && input[0].json.radarEmpty) {
  return [{
    json: {
      status: 'empty',
      generatedAt: new Date().toISOString(),
      count: 0,
      candidates: [],
      message: input[0].json.status
    }
  }];
}

const candidates = input
  .map(item => item.json)
  .filter(item => !item.radarEmpty)
  .sort((a, b) => b.viralScore - a.viralScore);

return [{
  json: {
    status: 'ready_for_ai',
    generatedAt: new Date().toISOString(),
    count: candidates.length,
    candidates
  }
}];
